import { isArray } from 'ut2';
import { BizFormItemUpload, BizFormItemUploadProps } from 'antd-more';
import { uploadFile } from '../../services';

const MAX_SIZE = 20 * 1024 * 1024;

export interface ItemUploadImageProps extends Partial<BizFormItemUploadProps> {
  onUploadAfter?: (res: { file: File; fssId: string }) => void;
}

const ItemUploadImage: React.FC<ItemUploadImageProps> = ({
  onUploadAfter,
  onUpload,
  ...restProps
}) => {
  return (
    <BizFormItemUpload
      type="image"
      maxCount={1}
      maxSize={MAX_SIZE}
      onUpload={async (file) => {
        const res = await (onUpload ? onUpload(file) : uploadFile(file));
        onUploadAfter?.({ file, fssId: res.fssid });
        return {
          fileId: res.fssid
        };
      }}
      extendRules={[
        {
          validator(_, value) {
            let hasUploading = false;
            let hasError = false;
            if (isArray(value) && value.length > 0) {
              value.some((item) => {
                if (item.status === 'error' && !item.response) {
                  hasError = true;
                  return true;
                }
                if (item.status === 'uploading') {
                  hasUploading = true;
                  return true;
                }
                return false;
              });
            }
            if (hasError) {
              return Promise.reject('\${label}\u542B\u6709\u4E0A\u4F20\u5931\u8D25\u6587\u4EF6');
            }
            return hasUploading ? Promise.reject() : Promise.resolve();
          }
        }
      ]}
      {...restProps}
    />
  );
};

export default ItemUploadImage;
